-- Save the date answers: who invited them (Maru or Fer) and whether they are family or friends.

alter table public.households
  add column side text check (side in ('maru', 'fer')),
  add column kind text check (kind in ('familia', 'amigos')),
  add column phone text,
  add column origin_city text,
  add column lodging text,
  add column extend_trip text,
  add column std_attending text,
  add column std_sent_at timestamptz,
  add column companion_count integer,
  add column teen_count integer,
  add column child_count integer;

create or replace function public.admin_update_household_tags(
  p_id uuid,
  p_side text,
  p_kind text
)
returns void
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_side text := nullif(lower(trim(p_side)), '');
  v_kind text := nullif(lower(trim(p_kind)), '');
begin
  if not public.is_admin() then
    raise exception 'not_admin';
  end if;
  if v_side is not null and v_side not in ('maru', 'fer') then
    raise exception 'bad_side';
  end if;
  if v_kind is not null and v_kind not in ('familia', 'amigos') then
    raise exception 'bad_kind';
  end if;
  update public.households
  set side = v_side,
      kind = v_kind
  where id = p_id;
end;
$fn$;

revoke all on function public.admin_update_household_tags(uuid, text, text) from public, anon;
grant execute on function public.admin_update_household_tags(uuid, text, text) to authenticated;

